{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Missing firewall rules for router security group",
      "resource": "nifcloud_router.negative",
      "severity": "HIGH",
      "explanation": "The router is associated with a security group, but the security group rules are not defined in this file. This could lead to unintended exposure or lack of necessary restrictions, depending on the default rules of the security group."
    }
  ],
  "patched_code": "resource "nifcloud_router" "negative" {
  security_group  = nifcloud_security_group.example.group_name

  network_interface {
    network_id = nifcloud_private_lan.main.id
  }
}

resource "nifcloud_security_group" "example" {
  group_name = "example"

  rule {
    action    = "ALLOW"
    protocol  = "TCP"
    from_port = 22
    to_port   = 22
    cidr_ip   = "0.0.0.0/0"
  }

  rule {
    action    = "ALLOW"
    protocol  = "TCP"
    from_port = 80
    to_port   = 80
    cidr_ip   = "0.0.0.0/0"
  }

  rule {
    action    = "ALLOW"
    protocol  = "TCP"
    from_port = 443
    to_port   = 443
    cidr_ip   = "0.0.0.0/0"
  }
}",
  "fix_summary": "Added a security group resource with explicit rules to allow SSH (port 22), HTTP (port 80), and HTTPS (port 443) traffic. This ensures the router has defined and controlled access."
}
